-- =============================================================================
-- 536 — LE CAHIER D'EXERCICES DE 1RE (partie 24)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/1re/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 536 --niveau 1re --fichiers histoire-geo.n3,histoire-geo.n4 --suffixe 24 > supabase/contenu/536_exercices_1re_24.sql
--
-- 63 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   histoire-geo.n3         33 exercices · 11 chapitres
--   histoire-geo.n4         30 exercices · 10 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('f4a8cf17-671f-5e39-b438-492e0ea466ea'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Trois villes, quatre chiffres","competence":"lire-tableau","situation":"Mira prépare un exposé sur la hiérarchie des métropoles. Elle a relevé quatre chiffres pour trois villes imaginaires et doit les rattacher aux critères de classement.","documents":[{"id":"villes","type":"tableau","titre":"Ardenne, Bastide et Cassel","source":"Chiffres inventés pour l’exercice.","colonnes":["","Ardenne","Bastide","Cassel"],"lignes":[["Sièges sociaux de grandes firmes",120,15,40],["Passagers de l’aéroport (millions par an)",85,12,60],["Étudiants (milliers)",150,60,90],["Organisations internationales installées",14,0,2]],"enteteLignes":true}],"questions":[{"enonce":"Touche la case qui chiffre la connectivité de Cassel.","aide":"La connectivité mesure l’insertion dans les réseaux de transport : cherche la ligne des passagers.","type":"zone","document":"villes","multiple":false},{"enonce":"Combien de fois Ardenne compte-t-elle plus de sièges sociaux que Cassel ?","aide":"Divise le nombre de sièges d’Ardenne par celui de Cassel.","type":"nombre","unite":"fois"},{"enonce":"Range chaque ligne du tableau selon le critère de classement qu’elle mesure.","aide":"Universités et étudiants relèvent du rayonnement culturel ; les institutions internationales, de l’influence politique.","type":"categories","categories":[{"id":"c0","texte":"Poids économique"},{"id":"c1","texte":"Rayonnement culturel"},{"id":"c2","texte":"Connectivité"},{"id":"c3","texte":"Influence politique"}],"items":[{"id":"i0","texte":"Étudiants (milliers)"},{"id":"i1","texte":"Sièges sociaux de grandes firmes"},{"id":"i2","texte":"Organisations internationales installées"},{"id":"i3","texte":"Passagers de l’aéroport"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c3"]},"explication":"La connectivité se lit dans les **aéroports**, les ports et les câbles : Cassel accueille **60 millions** de passagers par an."},{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3 fois","explication":"120 ÷ 40 = **3**. Les sièges sociaux mesurent le poids **économique** : Ardenne commande trois fois plus que Cassel."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c3","i3":"c2"}},"explication":"Sièges sociaux : **poids économique**. Étudiants : **rayonnement culturel**. Passagers : **connectivité**. Organisations internationales : **influence politique**."}]$ex$::jsonb),
  ('f4a8cf17-671f-5e39-b438-492e0ea466ea'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Plus peuplée, mais moins influente","competence":"analyser-document","situation":"Un journaliste compare quatre métropoles imaginaires. L’une est la plus peuplée de la liste, mais les investisseurs la citent rarement. Aide Inès à comprendre pourquoi.","documents":[{"id":"pop","type":"graphique","forme":"barres","titre":"Population des quatre métropoles","source":"Chiffres arrondis, inventés pour l’exercice.","categories":["Kantara","Nordheim","Soleira","Port-Aurore"],"series":[{"nom":"Population","valeurs":[22,11,18,9],"teinte":"violet"}],"axeY":{"titre":"Habitants","unite":"en millions","min":0,"max":25,"pas":5},"valeurs":false},{"id":"flux","type":"tableau","titre":"Insertion dans les flux mondiaux","source":"Chiffres inventés pour l’exercice.","colonnes":["","Kantara","Nordheim","Soleira","Port-Aurore"],"lignes":[["Destinations aériennes directes",20,140,30,110],["Sièges sociaux de grandes firmes",4,90,6,55]],"enteteLignes":true}],"questions":[{"enonce":"Touche la métropole la plus peuplée.","aide":"Cherche la barre la plus haute.","type":"zone","document":"pop","multiple":false},{"enonce":"Touche la case qui mesure la connectivité de Kantara.","aide":"La connectivité se lit dans les liaisons aériennes, pas dans les sièges sociaux.","type":"zone","document":"flux","multiple":false},{"enonce":"Combien de fois Nordheim a-t-elle plus de destinations aériennes directes que Kantara ?","aide":"Divise 140 par 20.","type":"nombre","unite":"fois"},{"enonce":"Que montre la comparaison de Kantara et de Nordheim ?","aide":"Compare le rang de population et le rang d’insertion dans les flux.","type":"choix","options":[{"id":"a","texte":"La population d’une métropole suffit à mesurer son influence mondiale"},{"id":"b","texte":"Une métropole très peuplée peut avoir peu de fonctions de commandement"},{"id":"c","texte":"Les métropoles les moins peuplées sont toujours les moins connectées"},{"id":"d","texte":"Le nombre de sièges sociaux ne dépend jamais de la connectivité"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k0"]},"explication":"**Kantara** compte 22 millions d’habitants : c’est la barre la plus haute."},{"cle":{"type":"zone","ids":["r0c1"]},"explication":"Kantara n’a que **20 destinations** aériennes directes : elle est peu connectée aux grands réseaux."},{"cle":{"type":"nombre","valeur":7,"tolerance":0},"affichage":"7 fois","explication":"140 ÷ 20 = **7**. Nordheim, deux fois moins peuplée, est bien plus reliée au monde."},{"cle":{"type":"choix","ids":["b"]},"explication":"Kantara est la plus peuplée mais la moins connectée : **la population ne fait pas les fonctions de commandement**. Beaucoup de métropoles du Sud sont dans ce cas."}]$ex$::jsonb),
  ('f4a8cf17-671f-5e39-b438-492e0ea466ea'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Quatre quartiers, une même métropole du Sud","competence":"observer-schema","situation":"Léo visite Port-Soleil, métropole imaginaire du Sud. Il lit un reportage et le confronte à un plan schématique de la ville pour comprendre ses inégalités internes.","documents":[{"id":"reportage","type":"texte","genre":"article","titre":"Un reportage à Port-Soleil","source":"Reportage imaginé pour l’exercice.","blocs":["Près du vieux port, un ancien quartier ouvrier a été rénové : les façades sont repeintes, les cafés ont changé de clientèle et les loyers ont doublé en dix ans. Beaucoup d’anciens habitants sont partis vivre plus loin.","De l’autre côté de l’avenue, un quartier résidentiel est entouré d’un haut mur. Des gardiens contrôlent l’entrée jour et nuit : seuls les habitants et leurs invités passent.","Derrière les tours de bureaux, des milliers de familles vivent dans des cabanes de tôle, sans eau courante. Le quartier d’affaires n’est qu’à dix minutes à pied."]},{"id":"plan","type":"schema","titre":"Plan schématique de Port-Soleil","source":"Schéma imaginé pour l’exercice.","largeur":340,"hauteur":250,"elements":[{"forme":"rect","x":8,"y":8,"l":324,"h":234,"teinte":"gris","motif":"aucun"},{"forme":"rect","x":18,"y":18,"l":148,"h":100,"teinte":"violet","motif":"clair","id":"z1","zone":true,"texte":"Quartier d’affaires"},{"forme":"rect","x":174,"y":18,"l":148,"h":100,"teinte":"ambre","motif":"clair","id":"z2","zone":true,"texte":"Centre ancien rénové"},{"forme":"rect","x":18,"y":126,"l":148,"h":100,"teinte":"corail","motif":"clair","id":"z3","zone":true,"texte":"Quartier précaire"},{"forme":"rect","x":174,"y":126,"l":148,"h":100,"teinte":"vert","motif":"clair","id":"z4","zone":true,"texte":"Résidence fermée"},{"forme":"emoji","x":40,"y":98,"emoji":"🏢","taille":22},{"forme":"emoji","x":196,"y":98,"emoji":"🏗️","taille":22},{"forme":"emoji","x":40,"y":206,"emoji":"🏚️","taille":22},{"forme":"emoji","x":196,"y":206,"emoji":"🏡","taille":22}]}],"questions":[{"enonce":"Touche, sur le plan, l’espace décrit dans le deuxième paragraphe du reportage.","aide":"Cherche le quartier protégé par un mur et des gardiens.","type":"zone","document":"plan","multiple":false},{"enonce":"Range chaque observation du reportage dans le phénomène qu’elle illustre.","aide":"La gentrification chasse les anciens habitants ; la ségrégation sépare les groupes ; le troisième phénomène juxtapose richesse et misère.","type":"categories","categories":[{"id":"c0","texte":"Gentrification"},{"id":"c1","texte":"Ségrégation socio-spatiale"},{"id":"c2","texte":"Quartier d’affaires et bidonville côte à côte"}],"items":[{"id":"i0","texte":"Les loyers doublent et les anciens habitants s’en vont"},{"id":"i1","texte":"Des familles sans eau courante derrière des tours"},{"id":"i2","texte":"Des cabanes de tôle à dix minutes à pied des bureaux"},{"id":"i3","texte":"Un mur et des gardiens contrôlent l’entrée"},{"id":"i4","texte":"Les cafés changent de clientèle"},{"id":"i5","texte":"Un quartier réservé aux habitants et à leurs invités"}]},{"enonce":"Touche l’espace du plan qui ressemble à Dharavi, à Bombay : un bidonville proche d’un quartier d’affaires.","aide":"Il se trouve juste sous le quartier d’affaires, comme dans le troisième paragraphe.","type":"zone","document":"plan","multiple":false},{"enonce":"Que montrent ensemble le reportage et le plan ?","aide":"Relis les trois paragraphes : que partagent-ils ?","type":"choix","options":[{"id":"a","texte":"Une métropole peut être riche et très inégale à l’intérieur d’elle-même"},{"id":"b","texte":"Les inégalités n’existent qu’entre métropoles, pas à l’intérieur"},{"id":"c","texte":"Une métropole qui se modernise fait disparaître ses quartiers pauvres"},{"id":"d","texte":"Les quartiers fermés sont une solution aux bidonvilles"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z4"]},"explication":"Un quartier résidentiel **clos et gardé**, c’est une *gated community* : la ségrégation socio-spatiale prend la forme d’un mur."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c2","i2":"c2","i3":"c1","i4":"c0","i5":"c1"}},"explication":"Loyers et clientèle qui changent : **gentrification**. Mur et gardiens : **ségrégation socio-spatiale**. Cabanes près des tours : la **coexistence** que l’on retrouve à Bombay avec Dharavi."},{"cle":{"type":"zone","ids":["z3"]},"explication":"Le **quartier précaire** touche le quartier d’affaires : c’est la situation de Dharavi, bidonville voisin des bureaux de Bombay."},{"cle":{"type":"choix","ids":["a"]},"explication":"Quartier d’affaires, centre gentrifié, résidence fermée et bidonville **cohabitent** : les inégalités se jouent aussi **dans** la métropole."}]$ex$::jsonb),
  ('8214dfca-5e27-5ec8-b7b7-18d2ad2f23e1'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Soixante-dix minutes pour aller travailler","competence":"analyser-texte","situation":"Lina habite avec ses parents dans un lotissement, loin de la métropole où travaille son père. Elle raconte un trajet qui ressemble à celui de milliers de familles.","documents":[{"id":"lina","type":"texte","genre":"recit","titre":"Le journal de Lina","source":"Texte écrit pour l’exercice.","blocs":["Ma famille a acheté une maison dans un lotissement récent, à 35 kilomètres de la métropole. Le terrain y coûtait beaucoup moins cher qu’en ville.","Mon père part à 6 h 30 pour rejoindre son bureau du quartier d’affaires. Il met 70 minutes à l’aller et 70 minutes au retour, cinq jours par semaine."]}],"questions":[{"enonce":"Touche le mot qui désigne le type d’habitat que la périurbanisation multiplie.","aide":"C’est le mot que Lina emploie pour parler de son quartier.","type":"zone","document":"lina","multiple":false},{"enonce":"Combien de minutes le père de Lina passe-t-il dans les transports en une semaine de travail ?","aide":"Un aller-retour dure 2 × 70 minutes ; il y en a cinq par semaine.","type":"nombre","unite":"minutes"},{"enonce":"Pourquoi la famille de Lina a-t-elle choisi de s’installer si loin ?","aide":"Relis la première phrase du journal.","type":"choix","options":[{"id":"a","texte":"Le quartier d’affaires s’y est installé récemment"},{"id":"b","texte":"Les loyers y sont plus élevés qu’au centre"},{"id":"c","texte":"La métropole a interdit de construire en ville"},{"id":"d","texte":"Le terrain y coûtait beaucoup moins cher qu’en ville"}],"multiple":false},{"enonce":"Complète la phrase de conclusion.","aide":"Le trajet va et vient comme le balancier d’une pendule.","type":"trous","segments":["Ce trajet quotidien entre le domicile et le travail est un déplacement ",0,". Il s’allonge à cause de la ",1,"."],"banque":["périurbanisation","ségrégation","pendulaire","gentrification"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8"]},"explication":"La périurbanisation étend les **lotissements** toujours plus loin de la ville, là où le foncier est moins cher."},{"cle":{"type":"nombre","valeur":700,"tolerance":0},"affichage":"700 minutes","explication":"70 × 2 × 5 = **700 minutes**, soit presque douze heures par semaine."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le **prix du foncier**, très élevé au centre, repousse les ménages vers les périphéries."},{"cle":{"type":"trous","trous":[["pendulaire"],["periurbanisation"]]},"affichage":"pendulaire · périurbanisation","explication":"Un **déplacement pendulaire** est un trajet quotidien domicile-travail ; la **périurbanisation** en allonge la distance."}]$ex$::jsonb),
  ('8214dfca-5e27-5ec8-b7b7-18d2ad2f23e1'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les docks de Port-Neuf changent de métier","competence":"se-reperer-temps","situation":"Tom étudie le quartier des docks de Port-Neuf, une métropole imaginaire. Il confronte la chronologie du quartier et l’évolution du prix de l’immobilier.","documents":[{"id":"frise","type":"frise","titre":"Histoire du quartier des docks","source":"Dates imaginées pour l’exercice.","debut":1960,"fin":2020,"pas":10,"periodes":[{"id":"z1","debut":1968,"fin":1998,"nom":"Friche","teinte":"brun"}],"evenements":[{"id":"z2","date":1968,"nom":"Dernier navire"},{"id":"z3","date":1998,"nom":"Plan de rénovation"},{"id":"z4","date":2006,"nom":"Quartier d’affaires"},{"id":"z5","date":2016,"nom":"Écoquartier"}]},{"id":"prix","type":"tableau","titre":"Prix de l’immobilier dans le quartier","source":"Chiffres inventés pour l’exercice.","colonnes":["Année","1985","2000","2020"],"lignes":[["Prix moyen du m² (€)",900,2700,9000]],"enteteLignes":true}],"questions":[{"enonce":"Touche l’événement qui met fin à l’activité portuaire du quartier.","aide":"Après lui, les quais sont à l’abandon.","type":"zone","document":"frise","multiple":false},{"enonce":"Pendant combien d’années les docks sont-ils restés une friche, avant le plan de rénovation ?","aide":"Mesure la période brune sur la frise.","type":"nombre","unite":"ans"},{"enonce":"Combien de fois le prix du m² de 2020 est-il supérieur à celui de 1985 ?","aide":"Divise 9 000 par 900.","type":"nombre","unite":"fois"},{"enonce":"Quel changement explique le mieux cette hausse des prix ?","aide":"Pense à ce que deviennent les friches portuaires des métropoles.","type":"choix","options":[{"id":"a","texte":"Le quartier est devenu un lieu de bureaux et de logements haut de gamme"},{"id":"b","texte":"Les habitants de ce quartier ont tous quitté la métropole pour le périurbain"},{"id":"c","texte":"Les docks ont repris peu à peu leur activité portuaire d’autrefois"},{"id":"d","texte":"La métropole a strictement limité les constructions près du centre"}],"multiple":false}]}$ex$::jsonb,
