  ('8214dfca-5e27-5ec8-b7b7-18d2ad2f23e1'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Où s’arrête la métropole ?","competence":"observer-schema","situation":"Un urbaniste dessine le plan d’une métropole imaginaire pour une réunion publique. Un élu affirme qu’elle s’arrête aux limites de la commune centrale : le plan dit autre chose.","documents":[{"id":"plan","type":"schema","titre":"Plan schématique d’une métropole","source":"Schéma imaginé pour l’exercice.","largeur":340,"hauteur":260,"elements":[{"forme":"ellipse","cx":170,"cy":140,"rx":158,"ry":112,"teinte":"vert","motif":"clair","id":"z1","zone":true},{"forme":"ellipse","cx":170,"cy":140,"rx":108,"ry":76,"teinte":"ambre","motif":"clair","id":"z2","zone":true},{"forme":"ellipse","cx":170,"cy":140,"rx":54,"ry":38,"teinte":"violet","motif":"clair","id":"z3","zone":true,"texte":"Centre"},{"forme":"texte","x":170,"y":84,"texte":"Banlieues","taille":"petit"},{"forme":"texte","x":170,"y":52,"texte":"Lotissements","taille":"petit"},{"forme":"cercle","cx":275,"cy":92,"r":12,"teinte":"corail","motif":"plein","id":"z4","zone":true},{"forme":"etiquette","x":232,"y":14,"texte":"Pôle B : bureaux, hôtels","vers":[270,82]},{"forme":"ligne","de":[224,140],"a":[334,140],"teinte":"brun","epaisseur":3},{"forme":"texte","x":296,"y":128,"texte":"Autoroute","taille":"petit","italique":true},{"forme":"rect","x":244,"y":150,"l":62,"h":22,"teinte":"bleu","motif":"clair","id":"z5","zone":true,"texte":"Entrepôts"},{"forme":"ligne","de":[46,176],"a":[118,150],"teinte":"violet","style":"pointilles","fleche":"fin","epaisseur":2},{"forme":"etiquette","x":70,"y":232,"texte":"Trajets quotidiens","vers":[72,164]}]},{"id":"elu","type":"texte","genre":"article","titre":"Propos d’un élu","source":"Propos imaginés pour l’exercice.","blocs":["« La métropole s’arrête là où s’arrête la commune centrale. Ce qu’il y a autour ne nous regarde pas. »"]}],"questions":[{"enonce":"Range ces espaces du centre vers l’extérieur, comme sur le plan.","aide":"Suis les cercles du plan, du plus petit au plus grand.","type":"ordre","items":[{"id":"a","texte":"Les banlieues"},{"id":"b","texte":"Le centre d’affaires"},{"id":"c","texte":"Les lotissements périurbains"}]},{"enonce":"Touche l’edge city : un pôle d’activités développé en périphérie.","aide":"Cherche un pôle d’activités loin du centre, dans la couronne extérieure.","type":"zone","document":"plan","multiple":false},{"enonce":"Touche l’équipement qui s’installe le long d’un grand axe de transport.","aide":"Il se trouve juste à côté de l’autoroute.","type":"zone","document":"plan","multiple":false},{"enonce":"Pourquoi les propos de l’élu ne décrivent-ils pas bien la métropole ?","aide":"Regarde la flèche pointillée et l’edge city : où vivent et travaillent les habitants ?","type":"choix","options":[{"id":"a","texte":"Les trajets et les activités débordent largement la commune centrale"},{"id":"b","texte":"Les limites administratives sont toujours plus larges que la métropole"},{"id":"c","texte":"Les périphéries ne comptent aucun habitant ni aucune activité"},{"id":"d","texte":"La commune centrale occupe en réalité toute la surface du plan"}],"multiple":false},{"enonce":"Complète : avec des pôles secondaires comme le pôle B, la métropole…","aide":"Le mot contient « centre » et « plusieurs ».","type":"trous","segments":["Avec la naissance de pôles comme le pôle B, la métropole se ",0,"."],"banque":["polycentrise","ferme","densifie","gentrifie"]}]}$ex$::jsonb,
