  ('20e28d7f-2957-5afb-a8b2-278ed88e13e6'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le rideau de fer de Valmont","competence":"lire-graphique","situation":"Sonia est née à Valmont, ville moyenne imaginaire. Elle lit un reportage sur le centre-ville, puis compare avec un graphique de la vacance des commerces.","documents":[{"id":"reportage","type":"texte","genre":"article","titre":"Le centre de Valmont","source":"Reportage imaginé pour l’exercice.","blocs":["À Valmont, 22 000 habitants, plusieurs boutiques de la rue principale ont baissé leur rideau. Les jeunes partent faire leurs études dans la métropole voisine et beaucoup ne reviennent pas.","En 2018, la ville est entrée dans le programme Action cœur de ville. Les habitants, eux, parlent encore d’un sentiment d’abandon."]},{"id":"vacance","type":"graphique","forme":"barres","titre":"Locaux commerciaux vides au centre de Valmont","source":"Chiffres inventés pour l’exercice.","categories":["2010","2015","2020","2023"],"series":[{"nom":"Locaux vides","valeurs":[6,9,14,12],"teinte":"corail"}],"axeY":{"titre":"Locaux commerciaux vides","unite":"en %","min":0,"max":16,"pas":2},"valeurs":false}],"questions":[{"enonce":"De combien de points la part de locaux vides a-t-elle augmenté entre 2010 et 2020 ?","aide":"Lis la hauteur des barres de 2010 et 2020, puis soustrais.","type":"nombre","unite":"points"},{"enonce":"Touche la première année où la part de locaux vides recule.","aide":"Cherche la première barre plus basse que la précédente.","type":"zone","document":"vacance","multiple":false},{"enonce":"Touche le mot qui dit ce que ressentent les habitants.","aide":"Il est dans la dernière phrase du reportage.","type":"zone","document":"reportage","multiple":false},{"enonce":"Range ces territoires : gagnent-ils de la croissance, ou sont-ils fragilisés par la métropolisation ?","aide":"La croissance se concentre dans une quinzaine d’aires urbaines.","type":"categories","categories":[{"id":"c0","texte":"Gagnent"},{"id":"c1","texte":"Fragilisés"}],"items":[{"id":"i0","texte":"Un espace rural i