","options":[{"id":"a","texte":"La population diminue alors que la ville se densifie"},{"id":"b","texte":"Les sols sont de moins en moins artificialisés"},{"id":"c","texte":"La métropole a limité ses constructions depuis 1990"},{"id":"d","texte":"L’étalement urbain consomme de plus en plus d’espace par habitant"}],"multiple":false},{"enonce":"Associe chaque constat du relevé au défi qu’il illustre.","aide":"Chaque constat correspond à l’un des quatre défis des métropoles françaises.","type":"association","gauche":[{"id":"g0","texte":"Un loyer qui monte de 40 % en dix ans"},{"id":"g1","texte":"Des files de voitures et un air irrespirable"},{"id":"g2","texte":"Une zone humide transformée en parking"},{"id":"g3","texte":"Un centre plus chaud lors des canicules"}],"droite":[{"id":"d0","texte":"L’adaptation au changement climatique"},{"id":"d1","texte":"La congestion et la pollution"},{"id":"d2","texte":"Le logement cher"},{"id":"d3","texte":"L’artificialisation des sols"}]}]}$ex$::jsonb,
