  ('b1fb68a5-161a-502e-9676-402d6c597ca0'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"L’usine de Kerlen ferme, puis rouvre","competence":"analyser-texte","situation":"Dans le bassin industriel imaginaire de Kerlen, l’entreprise Valtec a fermé une usine en 2004 avant d’en rouvrir une en 2022. Léa cherche ce qui a changé entre ces deux dates.","documents":[{"id":"emplois","type":"graphique","forme":"barres","titre":"Emplois industriels dans le bassin de Kerlen","source":"Chiffres inventés pour l’exercice.","categories":["1975","1990","2005","2023"],"series":[{"nom":"Emplois","valeurs":[420,300,210,190],"teinte":"brun"}],"axeY":{"titre":"Emplois industriels","unite":"en milliers","min":0,"max":450,"pas":50},"valeurs":false},{"id":"valtec","type":"texte","genre":"article","titre":"L’histoire d’une usine","source":"Texte écrit pour l’exercice.","blocs":["En 2004, l’entreprise Valtec ferme son usine de pompes de Kerlen et transfère la production en Asie, où les salaires sont alors bien plus bas.","En 2022, elle rouvre une usine à Kerlen. Les salaires asiatiques ont beaucoup augmenté, le transport coûte plus cher et les robots rendent la fabrication locale moins coûteuse. Valtec veut aussi ne plus dépendre d’un seul fournisseur pour des pièces essentielles."]}],"questions":[{"enonce":"Combien d’emplois industriels (en milliers) le bassin a-t-il perdus entre 1975 et 2005 ?","aide":"Soustrais la valeur de 2005 à celle de 1975.","type":"nombre","unite":"milliers"},{"enonce":"Touche le mot qui désigne la technologie rendant la fabrication locale moins coûteuse.","aide":"Elle remplace une partie du travail humain dans l’usine.","type":"zone","document":"valtec","multiple":false},{"enonce":"Range chaque fait : relève-t-il d’une délocalisation ou d’une relocalisation ?","aide":"La délocalisation éloigne la production ; la relocalisation la rapproche.","type":"categories","categories":[{"id":"c0","texte":"Délocalisation"},{"id":"c1","texte":"Relocalisation"}],"items":[{"id":"i0","texte":"La recherche de souveraineté sur des pièces essentielles"},{"id":"i1","texte":"Fermeture d’une usine du Nord, production transférée en Asie"},{"id":"i2","texte":"Des salaires asiatiques qui augmentent"},{"id":"i3","texte":"Un transfert vers un pays aux coûts plus faibles"},{"id":"i4","texte":"Des robots qui diminuent l’écart de coût du travail"}]},{"enonce":"Que montre l’histoire de l’usine de Kerlen ?","aide":"Compare ce que dit le texte pour 2004 et pour 2022.","type":"choix","options":[{"id":"a","texte":"Un espace productif se gagne et se perd au rythme des stratégies d’entreprises"},{"id":"b","texte":"Les délocalisations sont définitives pour toutes les activités industrielles"},{"id":"c","texte":"Les salaires seuls décident toujours du lieu de production"},{"id":"d","texte":"Une usine fermée ne peut jamais être remplacée dans la même région"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":210,"tolerance":0},"affichage":"210 milliers","explication":"420 − 210 = **210 milliers** d’emplois : c’est la trace des délocalisations dans une région industrielle du Nord."},{"cle":{"type":"zone","ids":["m47"]},"explication":"La **robotisation** réduit l’écart de coût du travail : elle fait partie des facteurs qui poussent aux relocalisations."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0","i4":"c1"}},"explication":"Fermer pour produire ailleurs à moindre coût : **délocalisation**. Salaires qui montent, robots, souveraineté : autant de facteurs de **relocalisation**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Un espace productif **n’est jamais acquis** : stratégies d’entreprises et politiques publiques le font gagner ou perdre. Les salaires ne sont qu’un facteur parmi d’autres."}]$ex$::jsonb),
  ('b1fb68a5-161a-502e-9676-402d6c597ca0'::uuid, 3, 3, 15, 50, 4,
