   $ex${"titre":"Silvaire, la ville qui attire et qui coûte cher","competence":"analyser-document","situation":"Silvaire, ville imaginaire, est devenue un grand centre d’innovation. Une ingénieure y travaille ; elle raconte comment ses collègues et elle vivent cette réussite.","documents":[{"id":"loyers","type":"graphique","forme":"courbe","titre":"Loyer moyen d’un appartement à Silvaire","source":"Chiffres inventés pour l’exercice.","categories":["2005","2010","2015","2020"],"series":[{"nom":"Loyer","valeurs":[900,1100,1600,2200],"teinte":"violet"}],"axeY":{"titre":"Loyer mensuel","unite":"en euros","min":0,"max":2400,"pas":400}},{"id":"ingenieure","type":"texte","genre":"article","titre":"Témoignage d’une ingénieure","source":"Témoignage imaginé pour l’exercice.","blocs":["Je suis arrivée à Silvaire pour travailler dans un laboratoire de l’université. Beaucoup de start-up se sont installées ici parce qu’on y trouve des chercheurs et des investisseurs : le capital-risque finance leurs premiers produits.","Mais mon loyer a doublé en dix ans, et mes collègues cherchent à se loger de plus en plus loin."]}],"questions":[{"enonce":"Touche le mot qui désigne l’argent investi dans les jeunes entreprises innovantes.","aide":"Le mot contient une idée de « risque ».","type":"zone","document":"ingenieure","multiple":false},{"enonce":"Combien de fois le loyer de 2020 est-il plus élevé que celui de 2010 ?","aide":"Divise 2 200 par 1 100.","type":"nombre","unite":"fois"},{"enonce":"Associe chaque acteur de l’écosystème d’innovation à son rôle.","aide":"Chaque acteur intervient à une étape différente : formation, recherche, produit, financement.","type":"association","gauche":[{"id":"g0","texte":"Les universités"},{"id":"g1","texte":"Les laboratoires"},{"id":"g2","texte":"Les start-up"},{"id":"g3","texte":"Le capital-risque"}],"droite":[{"id":"d0","texte":"Ils produisent la recherche"},{"id":"d1","texte":"Elles transforment les idées en produits"},{"id":"d2","texte":"Il finance l