   $ex${"titre":"Le port et son arrière-pays","competence":"observer-schema","situation":"Un géographe dessine le schéma d’un grand port à conteneurs. Il veut montrer pourquoi les usines lourdes s’installent au bord de l’eau et jusqu’où le port rayonne à l’intérieur des terres.","documents":[{"id":"port","type":"schema","titre":"Un port, sa ZIP et son arrière-pays","source":"Schéma imaginé pour l’exercice.","largeur":340,"hauteur":250,"elements":[{"forme":"rect","x":8,"y":8,"l":108,"h":234,"teinte":"bleu","motif":"clair"},{"forme":"texte","x":62,"y":28,"texte":"Mer","taille":"petit","italique":true},{"forme":"polygone","points":[[22,112],[98,112],[86,134],[34,134]],"teinte":"gris","motif":"plein"},{"forme":"rect","x":62,"y":98,"l":22,"h":14,"teinte":"ambre","motif":"plein"},{"forme":"rect","x":40,"y":100,"l":18,"h":12,"teinte":"corail","motif":"plein"},{"forme":"texte","x":62,"y":156,"texte":"Navire géant","taille":"petit"},{"forme":"rect","x":116,"y":8,"l":20,"h":234,"teinte":"gris","motif":"plein"},{"forme":"rect","x":148,"y":18,"l":184,"h":68,"teinte":"ambre","motif":"clair","id":"z1","zone":true,"texte":"Raffineries, sidérurgie"},{"forme":"texte","x":240,"y":112,"texte":"Arrière-pays desservi","taille":"normal","italique":true},{"forme":"texte","x":330,"y":150,"texte":"Fleuve","taille":"petit","ancre":"fin"},{"forme":"ligne","de":[142,160],"a":[330,160],"teinte":"bleu","epaisseur":3,"fleche":"fin","id":"z2","zone":true},{"forme":"texte","x":330,"y":190,"texte":"Voie ferrée","taille":"petit","ancre":"fin"},{"forme":"ligne","de":[142,200],"a":[330,200],"teinte":"gris","epaisseur":3,"style":"pointilles","fleche":"fin","id":"z3","zone":true},{"forme":"texte","x":330,"y":220,"texte":"Autoroute","taille":"petit","ancre":"fin"},{"forme":"ligne","de":[142,230],"a":[330,230],"teinte":"brun","epaisseur":3,"fleche":"fin","id":"z4","zone":true}]}],"questions":[{"enonce":"Touche la zone qui associe raffineries et sidérurgie au bord du quai : la ZIP.","aide":"Elle touche directement le quai, côté terre.","type":"zone","document":"port","multiple":false},{"enonce":"Touche les trois voies qui prolongent le port vers l’arrière-pays.","aide":"Il y a un fleuve, une voie ferrée et une route.","type":"zone","document":"port","multiple":true},{"enonce":"Pourquoi les industries lourdes s’installent-elles près du quai ?","aide":"Minerai, pétrole, charbon : que coûte le fait de les décharger puis de les recharger ?","type":"choix","options":[{"id":"a","texte":"Elles évitent des ruptures de charge coûteuses sur des matières pondéreuses"},{"id":"b","texte":"Elles profitent de la proximité des centres de recherche des métropoles"},{"id":"c","texte":"Elles cherchent à s’éloigner des flux de marchandises du monde"},{"id":"d","texte":"Elles n’ont besoin ni de terrain disponible ni de grands navires"}],"multiple":false},{"enonce":"Complète la définition.","aide":"Le mot vient de l’allemand : « le pays de derrière ».","type":"trous","segments":["L’arrière-pays qu’un port dessert s’appelle son ",0,"."],"banque":["cluster","technopôle","littoral","hinterland"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"La **zone industrialo-portuaire** réunit port en eau profonde, raffineries, sidérurgie, pétrochimie et logistique."},{"cle":{"type":"zone","ids":["z2","z3","z4"]},"explication":"Le **fleuve**, la **voie ferrée** et l’**autoroute** étendent l’hinterland du port : plus elles sont efficaces, plus l’arrière-pays desservi est vaste."},{"cle":{"type":"choix","ids":["a"]},"explication":"Décharger puis recharger des matières **pondéreuses** coûte cher (rupture de charge). Au bord du quai, l’usine reçoit la marchandise directement du navire."},{"cle":{"type":"trous","trous":[["hinterland"]]},"affichage":"hinterland","explication":"Le **hinterland** est l’arrière-pays d’un port ; les voies ferrées, les fleuves et les autoroutes l’étendent."}]$ex$::jsonb),
