   $ex${"titre":"La côte ou l’intérieur ? Le dilemme de Norvane","competence":"raisonner","situation":"L’entreprise imaginaire Norvane veut construire une aciérie. Deux sites sont possibles : l’un sur la côte, l’autre à 300 km dans les terres. Son directeur compare coûts et risques.","documents":[{"id":"sites","type":"tableau","titre":"Deux sites pour l’aciérie","source":"Chiffres inventés pour l’exercice.","colonnes":["","Site A : sur la côte","Site B : dans les terres"],"lignes":[["Coût du transport du minerai (€ par tonne)",8,22],["Terrain disponible pour s’étendre (hectares)",400,90],["Exposition à la submersion et aux tempêtes","Forte","Faible"],["Ruptures de charge entre le navire et l’usine","Aucune","Deux"]],"enteteLignes":true},{"id":"directeur","type":"texte","genre":"lettre","titre":"La note du directeur","source":"Note imaginée pour l’exercice.","blocs":["« Sur la côte, le minerai passe du navire à l’usine sans être touché. Mais le niveau de la mer monte, les tempêtes se multiplient et notre assureur s’inquiète. »"]}],"questions":[{"enonce":"Quel écart de coût de transport du minerai (en euros par tonne) sépare les deux sites ?","aide":"Soustrais le coût du site A à celui du site B.","type":"nombre","unite":"€ par tonne"},{"enonce":"Touche la case qui montre la fragilité du site A.","aide":"Cherche le risque naturel lié à la proximité de la mer.","type":"zone","document":"sites","multiple":false},{"enonce":"Pour une activité qui manipule de grandes masses de minerai, quel site est le plus avantageux économiquement ?","aide":"Compare le coût de transport et le nombre de ruptures de charge.","type":"choix","options":[{"id":"a","texte":"Le site B, dans les terres"},{"id":"b","texte":"Le site A, sur la côte"},{"id":"c","texte":"Aucun des deux sites n’est exploitable"},{"id":"d","texte":"Les deux sites sont équivalents"}],"multiple":false},{"enonce":"Range chaque élément : est-ce un atout de la littoralisation ou une de ses fragilités ?","aide":"Un atout fait gagner de l’argent ou de la place ; une fragilité fait courir un risque.","type":"categories","categories":[{"id":"c0","texte":"Atout"},{"id":"c1","texte":"Fragilité"}],"items":[{"id":"i0","texte":"Un terrain vaste pour s’étendre"},{"id":"i1","texte":"L’accès direct aux navires géants"},{"id":"i2","texte":"La congestion et la pollution autour du port"},{"id":"i3","texte":"Aucune rupture de charge"},{"id":"i4","texte":"La submersion et les tempêtes"}]},{"enonce":"Quelle formule résume la situation de Norvane ?","aide":"Relie les chiffres du tableau au risque que décrit le directeur.","type":"choix","options":[{"id":"a","texte":"Une localisation sans avantage économique ni risque particulier"},{"id":"b","texte":"Une localisation sûre sur le plan climatique et très coûteuse"},{"id":"c","texte":"Une localisation efficace économiquement mais fragile écologiquement"},{"id":"d","texte":"Une localisation fragile économiquement mais très sûre écologiquement"}],"multiple":false}]}$ex$::jsonb,
