   $ex${"titre":"Un navire bloque le canal, une usine s’arrête","competence":"analyser-texte","situation":"Sofie dirige une usine de meubles à Lyon. Elle raconte ce qui s’est passé quand un événement réel, le blocage du canal de Suez en 2021, a dérangé ses livraisons.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"Le récit de Sofie","source":"Récit écrit pour l’exercice, d’après un événement réel de mars 2021.","blocs":["En mars 2021, un porte-conteneurs géant s’échoue en travers du canal de Suez. Pendant près d’une semaine, la circulation est interrompue.","Mon usine fonctionne en flux tendu : je n’ai presque pas de stock de visserie, qui m’arrive d’Asie juste à temps. Quand le canal est bloqué, les conteneurs ne passent plus."]},{"id":"chaine","type":"chaine","disposition":"colonne","titre":"Les conséquences du blocage","noeuds":[{"id":"z1","texte":"Un navire bloque le canal","emoji":"🚢"},{"id":"z2","texte":"Des centaines de navires attendent","emoji":"⏳"},{"id":"z3","texte":"Les livraisons sont retardées","emoji":"📦"},{"id":"z4","texte":"?"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"}]}],"questions":[{"enonce":"Touche le mot qui désigne ce que le flux tendu cherche à limiter.","aide":"Sofie en a « presque pas ».","type":"zone","document":"recit","multiple":false},{"enonce":"Que met-on à la place du point d’interrogation, dans la chaîne des conséquences ?","aide":"Sofie n’a presque pas de stock : que se passe-t-il quand la visserie n’arrive pas ?","type":"choix","options":[{"id":"a","texte":"L’usine, privée de pièces, doit ralentir ou s’arrêter"},{"id":"b","texte":"Les stocks de visserie de l’usine augmentent"},{"id":"c","texte":"Les conteneurs sont livrés avant la date prévue"},{"id":"d","texte":"Les usines concurrentes baissent leurs prix de vente"}],"multiple":false},{"enonce":"Range chaque élément : vulnérabilité révélée ou réponse des entreprises ?","aide":"Le blocage révèle une faiblesse ; les entreprises cherchent ensuite à s’en protéger.","type":"categories","categories":[{"id":"c0","texte":"Vulnérabilité révélée"},{"id":"c1","texte":"Réponse des entreprises"}],"items":[{"id":"i0","texte":"Diversifier les fournisseurs"},{"id":"i1","texte":"Régionaliser une partie de la production"},{"id":"i2","texte":"Constituer des stocks plus importants"},{"id":"i3","texte":"Un seul navire peut bloquer le commerce mondial"},{"id":"i4","texte":"La dépendance à quelques fournisseurs"}]},{"enonce":"Complète la conclusion de Sofie.","aide":"L’expression désigne une organisation qui livre au moment voulu.","type":"trous","segments":["Chaque incident révèle la fragilité du ",0," tendu."],"banque":["stock","flux","circuit"]}]}$ex$::jsonb,
