   $ex${"titre":"Une commande qui voyage avant le sac","competence":"analyser-document","situation":"Océane, petite entreprise nantaise imaginaire, vend des sacs de sport fabriqués en Asie. Un client passe commande sur son site : avant que le sac ne bouge, tout circule déjà par les réseaux.","documents":[{"id":"dossier","type":"texte","genre":"article","titre":"Le dossier d’Océane","source":"Situation imaginée pour l’exercice.","blocs":["Océane a acheté 30 % du capital d’une usine asiatique. Son ingénieur s’est formé deux ans à Shenzhen avant de revenir à Nantes. L’entreprise paie une licence pour un tissu breveté.","Les commandes passent par un câble sous-marin jusqu’à un data center, et l’ordre de fabrication part vers l’usine en quelques secondes. Le suivi du colis circule ensuite en temps réel.","Océane hésite à produire plus près de ses clients : cela réduirait les trajets en bateau et en avion, mais coûterait plus cher."]},{"id":"chaine","type":"chaine","disposition":"ligne","titre":"Le parcours d’une commande","noeuds":[{"id":"z1","texte":"Commande en ligne","emoji":"🖱️"},{"id":"z2","texte":"Ordre transmis à l’usine","emoji":"📡"},{"id":"z3","texte":"Fabrication du sac","emoji":"🏭"},{"id":"z4","texte":"Envoi par conteneur","emoji":"🚢"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"}]}],"questions":[{"enonce":"Range chaque fait du dossier selon le flux immatériel qu’il illustre.","aide":"Capitaux : argent investi. Données : informations. Savoir-faire : compétences, brevets, licences.","type":"categories","categories":[{"id":"c0","texte":"Flux de capitaux"},{"id":"c1","texte":"Flux de données"},{"id":"c2","texte":"Flux de savoir-faire"}],"items":[{"id":"i0","texte":"L’achat de 30 % d’une usine asiatique"},{"id":"i1","texte":"La commande transmise par un câble sous-marin"},{"id":"i2","texte":"Un ingénieur formé deux ans à Shenzhen"},{"id":"i3","texte":"Le suivi du colis en temps réel"},{"id":"i4","texte":"Une licence payée pour un tissu breveté"}]},{"enonce":"Touche les deux étapes qui ne sont, à ce stade, que de l’information.","aide":"Rien de matériel n’a encore bougé : ni sac, ni conteneur.","type":"zone","document":"chaine","multiple":true},{"enonce":"Que signifie : « La marchandise suit le flux de données, pas l’inverse » ?","aide":"Observe l’ordre des quatre étapes du parcours.","type":"choix","options":[{"id":"a","texte":"Les données n’ont aucun rôle dans la production"},{"id":"b","texte":"L’information part avant et commande le déplacement des biens"},{"id":"c","texte":"Les biens voyagent toujours plus vite que les données"},{"id":"d","texte":"Les marchandises circulent sans qu’on les commande"}],"multiple":false},{"enonce":"Quel type de projet répond à l’hésitation d’Océane sur le coût écologique des trajets ?","aide":"Le transport maritime et aérien pèse lourd dans les émissions de gaz à effet de serre.","type":"choix","options":[{"id":"a","texte":"Des circuits plus courts, plus proches des clients"},{"id":"b","texte":"Des chaînes de production encore plus longues"},{"id":"c","texte":"La suppression de toute fabrication industrielle"},{"id":"d","texte":"Une augmentation du nombre de trajets aériens"}],"multiple":false}]}$ex$::jsonb,
