  ('82e58c7b-52f7-5f9f-ac3c-0666a1a8c1a1'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Moins d’emplois, mais autant d’exportations","competence":"lire-tableau","situation":"Zoé a lu que l’industrie française pesait deux fois moins qu’autrefois. Elle se demande si cela veut dire qu’elle n’exporte plus rien : elle compare plusieurs chiffres.","documents":[{"id":"pib","type":"graphique","forme":"barres","titre":"Part de l’industrie dans le PIB","source":"Chiffres arrondis.","categories":["Années 1970","Aujourd’hui"],"series":[{"nom":"Part de l’industrie","valeurs":[26,13],"teinte":"brun"}],"axeY":{"titre":"Part du PIB","unite":"en %","min":0,"max":30,"pas":5},"valeurs":false},{"id":"filieres","type":"tableau","titre":"Quatre filières industrielles","source":"Chiffres inventés pour l’exercice.","colonnes":["Filière","Part de l’emploi industriel (%)","Part des exportations industrielles (%)"],"lignes":[["Aéronautique",5,15],["Textile",4,2],["Automobile",9,7],["Agroalimentaire",16,14]],"enteteLignes":true}],"questions":[{"enonce":"Combien de fois la part de l’industrie dans le PIB était-elle plus forte dans les années 1970 qu’aujourd’hui ?","aide":"Divise 26 par 13.","type":"nombre","unite":"fois"},{"enonce":"Touche la case qui montre qu’une filière pèse beaucoup dans les exportations.","aide":"Cherche la plus forte part des exportations, pour une filière qui emploie peu.","type":"zone","document":"filieres","multiple":false},{"enonce":"Pour l’aéronautique, combien de fois la part dans les exportations est-elle plus forte que la part dans l’emploi ?","aide":"Divise 15 par 5.","type":"nombre","unite":"fois"},{"enonce":"Range chaque territoire selon sa trajectoire.","aide":"Pense à la carte des inégalités : le Nord et l’Est industriels s’opposent à l’Ouest.","type":"categories","categories":[{"id":"c0","texte":"Gagne des emplois"},{"id":"c1","texte":"A perdu des centaines de milliers d’emplois depuis 1975"},{"id":"c2","texte":"Concentre sièges et recherche"}],"items":[{"id":"i0","texte":"Le Nord industriel"},{"id":"i1","texte":"L’Est industriel"},{"id":"i2","texte":"L’Île-de-France"},{"id":"i3","texte":"L’Ouest"},{"id":"i4","texte":"Le Sud-Ouest"}]},{"enonce":"Que conclure du tableau et du graphique réunis ?","aide":"Compare le graphique (le poids global) et la ligne de l’aéronautique.","type":"choix","options":[{"id":"a","texte":"L’industrie pèse moins dans le PIB mais certaines filières exportent beaucoup"},{"id":"b","texte":"Toutes les filières pèsent autant dans l’emploi que dans les exportations"},{"id":"c","texte":"L’industrie française a disparu et n’exporte plus rien"},{"id":"d","texte":"La désindustrialisation a touché toutes les filières de la même manière"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2 fois","explication":"26 ÷ 13 = **2** : l’industrie pèse deux fois moins dans le PIB. C’est la désindustrialisation."},{"cle":{"type":"zone","ids":["r0c2"]},"explication":"**15 %** des exportations industrielles pour seulement 5 % de l’emploi : l’aéronautique exporte bien plus qu’elle n’emploie."},{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3 fois","explication":"15 ÷ 5 = **3** : une industrie qui pèse moins dans l’emploi peut peser encore beaucoup dans les exportations."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c2","i3":"c0","i4":"c0"}},"explication":"L’**Ouest** et le **Sud-Ouest** gagnent des emplois ; le **Nord** et l’**Est** industriels en ont perdu des centaines de milliers ; l’**Île-de-France** concentre sièges et recherche."},{"cle":{"type":"choix","ids":["a"]},"explication":"La **désindustrialisation** est réelle, mais l’industrie reste puissante dans quelques filières exportatrices comme l’**aéronautique**."}]$ex$::jsonb),
  ('82e58c7b-52f7-5f9f-ac3c-0666a1a8c1a1'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La carte des gagnants et des perdants, et la friche de Valbourg","competence":"analyser-document","situation":"Lucie compare la carte des territoires qui gagnent ou perdent des emplois à l’histoire d’une usine imaginaire du Nord. Elle veut comprendre comment une région industrielle peut se transformer.","documents":[{"id":"carte","type":"carte","titre":"Emploi et trajectoires des régions","source":"Carte schématique.","fond":"france","regionsCliquables":true,"regions":[{"code":"IDF","teinte":"violet","motif":"plein"},{"code":"BRE","teinte":"vert","motif":"clair"},{"code":"PDL","teinte":"vert","motif":"clair"},{"code":"NAQ","teinte":"vert","motif":"clair"},{"code":"HDF","teinte":"corail","motif":"hachures"},{"code":"GES","teinte":"corail","motif":"hachures"}],"legende":[{"teinte":"violet","motif":"plein","texte":"Sièges et recherche"},{"teinte":"vert","motif":"clair","texte":"Gagne des emplois"},{"teinte":"corail","motif":"hachures","texte":"Désindustrialisation"}]},{"id":"valbourg","type":"texte","genre":"article","titre":"L’usine de Valbourg","source":"Texte écrit pour l’exercice.","blocs":["En 1992, l’usine de tissage de Valbourg, dans le Nord, ferme ses portes après un siècle d’activité. Plus de mille emplois disparaissent.","Le site reste une friche pendant vingt ans. En 2015, la ville le réhabilite : un lycée, une médiathèque et des bureaux s’installent dans les anciens ateliers."]}],"questions":[{"enonce":"Touche la région qui concentre les sièges sociaux et la recherche.","aide":"C’est la région de la capitale.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche les deux régions du Nord et de l’Est qui ont perdu des centaines de milliers d’emplois depuis 1975.","aide":"Ce sont les régions du Nord et de l’Est, voisines de la Belgique et de l’Allemagne.","type":"zone","document":"carte","multiple":true},{"enonce":"Touche le mot qui désigne un ancien site de production abandonné.","aide":"Le site « reste » ainsi pendant vingt ans.","type":"zone","document":"valbourg","multiple":false},{"enonce":"Range les étapes de l’histoire du site de Valbourg.","aide":"Suis les dates : 1992, puis vingt ans plus tard.","type":"ordre","items":[{"id":"a","texte":"Le site devient une friche"},{"id":"b","texte":"L’usine de tissage ferme"},{"id":"c","texte":"Un lycée, une médiathèque et des bureaux s’y installent"},{"id":"d","texte":"La ville réhabilite les anciens ateliers"}]},{"enonce":"Qu’illustre l’histoire de Valbourg dans le cas de la carte ?","aide":"Le Nord est colorié en hachures sur la carte : relis la légende.","type":"choix","options":[{"id":"a","texte":"La désindustrialisation du Nord et la reconversion de ses friches"},{"id":"b","texte":"La fin de toute activité économique dans les anciennes régions industrielles"},{"id":"c","texte":"La croissance des emplois industriels dans les régions de l’Ouest"},{"id":"d","texte":"La concentration des sièges sociaux dans les villes du Nord"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["IDF"]},"explication":"L’**Île-de-France** concentre les sièges et la recherche : c’est le cœur des fonctions de commandement du pays."},{"cle":{"type":"zone","ids":["HDF","GES"]},"explication":"Les **Hauts-de-France** et le **Grand Est** ont le plus souffert de la désindustrialisation : leurs mines, usines textiles et sidérurgiques ont fermé."},{"cle":{"type":"zone","ids":["m28"]},"explication":"Une **friche industrielle** est un ancien site de production abandonné ; elle peut être reconvertie, comme à Valbourg."},{"cle":{"type":"ordre","ids":["b","a","d","c"]},"explication":"Fermeture (1992) → **friche** → réhabilitation (2015) → **nouveaux usages**. C’est la reconversion type d’un territoire désindustrialisé."},{"cle":{"type":"choix","ids":["a"]},"explication":"Valbourg illustre la **désindustrialisation** du Nord et la **reconversion** de ses friches industrielles, comme à Euralille ou dans le Nord-Pas-de-Calais."}]$ex$::jsonb),
  ('f944fe8e-b8af-5617-b96f-89ae6c55ad0e'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Avec qui la France commerce-t-elle ?","competence":"lire-graphique","situation":"Maxime prépare une fiche sur l’insertion de la France dans le monde. Il observe d’abord le partage de ses échanges, puis il situe quelques grandes portes d’entrée du pays.","documents":[{"id":"echanges","type":"graphique","forme":"secteurs","titre":"Les échanges de la France","source":"Chiffres arrondis.","categories":["Union européenne","Reste du monde"],"series":[{"nom":"Échanges","valeurs":[60,40]}]},{"id":"carte","type":"carte","titre":"Quatre villes françaises","fond":"france","lieux":[{"id":"z1","lieu":"le-havre","symbole":"lettre","lettre":"A"},{"id":"z2","lieu":"marseille","symbole":"lettre","lettre":"B"},{"id":"z3","lon":2.55,"lat":49.01,"symbole":"lettre","lettre":"C"},{"id":"z4","lieu":"clermont-ferrand","symbole":"lettre","lettre":"D"}]}],"questions":[{"enonce":"Touche le premier partenaire commercial de la France.","aide":"Cherche la plus grande part du graphique.","type":"zone","document":"echanges","multiple":false},{"enonce":"Quelle part des échanges de la France se fait avec le reste du monde ?","aide":"Les deux parts font 100 %.","type":"nombre","unite":"%"},{"enonce":"Touche les trois portes d’entrée de rang international : Roissy, Le Havre et Marseille.","aide":"Roissy est l’aéroport de Paris ; la quatrième ville, au centre du pays, n’en fait pas partie.","type":"zone","document":"carte","multiple":true},{"enonce":"Que protège une AOP, comme celle du comté ?","aide":"Le comté vient d’un lieu précis et d’une façon précise de le fabriquer.","type":"choix","options":[{"id":"a","texte":"Une entreprise contre la délocalisation de ses usines"},{"id":"b","texte":"Une marque vendue uniquement à l’étranger"},{"id":"c","texte":"Un produit lié à un terroir et à un savoir-faire"},{"id":"d","texte":"Un produit fabriqué dans plusieurs pays à la fois"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k0"]},"explication":"L’**Union européenne** reçoit environ **60 %** des échanges de la France : c’est son premier partenaire."},{"cle":{"type":"nombre","valeur":40,"tolerance":0},"affichage":"40 %","explication":"100 − 60 = **40 %** avec le reste du monde."},{"cle":{"type":"zone","ids":["z1","z2","z3"]},"explication":"**A** (Le Havre), **B** (Marseille) et **C** (Roissy) sont de rang international. **D** est Clermont-Ferrand, ville de l’intérieur."},{"cle":{"type":"choix","ids":["c"]},"explication":"Les signes de qualité (AOP, AOC, IGP, Label rouge) protègent un **savoir-faire lié à un lieu** : champagne, comté, roquefort."}]$ex$::jsonb),
  ('f944fe8e-b8af-5617-b96f-89ae6c55ad0e'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Deux entreprises, deux manières de vivre dans la mondialisation","competence":"lire-tableau","situation":"Eva compare deux entreprises imaginaires installées en France. L’une fabrique des produits liés à un lieu, l’autre fabrique pour la grande distribution mondiale. Elle se demande laquelle peut déménager.","documents":[{"id":"entreprises","type":"tableau","titre":"Deux entreprises françaises","source":"Entreprises imaginées pour l’exercice.","colonnes":["","Fromagerie des Cimes","Électro-Vallée"],"lignes":[["Produit","Fromage d’AOP, vendu en France et à l’étranger","Lave-linge pour la grande distribution"],["Pourquoi le produire ici ?","Le fromage est lié à son terroir","Les coûts de production sont comparés pays par pays"],["Peut-elle délocaliser ?","Non","Oui, si les coûts sont plus bas ailleurs"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la case qui explique pourquoi la fromagerie ne peut pas délocaliser.","aide":"Cherche la ligne « Pourquoi le produire ici ? ».","type":"zone","document":"entreprises","multiple":false},{"enonce":"Range chaque activité : est-elle facilement délocalisable ou non ?","aide":"Une activité est non délocalisable quand elle dépend d’un lieu ou d’une clientèle de proximité.","type":"categories","categories":[{"id":"c0","texte":"Facilement délocalisable"},{"id":"c1","texte":"Non délocalisable"}],"items":[{"id":"i0","texte":"Un artisan d’art installé dans son village"},{"id":"i1","texte":"Un gîte rural en Auvergne"},{"id":"i2","texte":"Une boulangerie de quartier"},{"id":"i3","texte":"Assembler des lave-linge pour la grande distribution"},{"id":"i4","texte":"Un centre d’appels pour un opérateur de téléphone"}]},{"enonce":"Complète le bilan d’Eva.","aide":"La fromagerie appartient à la deuxième stratégie.","type":"trous","segments":["Deux stratégies coexistent : produire pour le ",0,", et produire ce que le monde ne peut pas ",1,"."],"banque":["monde","détruire","taxer","copier"]},{"enonce":"Quel arbitrage les systèmes productifs français doivent-ils faire ?","aide":"Une entreprise doit être compétitive, mais aussi rester liée à son territoire.","type":"choix","options":[{"id":"a","texte":"Entre l’Union européenne et le reste du monde, sans pouvoir commercer avec les deux"},{"id":"b","texte":"Entre industrie et agriculture, qui s’excluent toujours"},{"id":"c","texte":"Entre compétitivité et ancrage territorial"},{"id":"d","texte":"Entre production et vente, deux activités qui ne se rencontrent jamais"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"Le fromage d’AOP est **lié à son terroir** : le déplacer reviendrait à changer le produit. L’emploi y est non délocalisable."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c1","i3":"c0","i4":"c0"}},"explication":"Tourisme, artisanat lié au terroir et **services de proximité** sont **non délocalisables** ; l’assemblage standard et un centre d’appels peuvent aller où les coûts sont bas."},{"cle":{"type":"trous","trous":[["monde"],["copier"]]},"affichage":"monde · copier","explication":"Électro-Vallée **produit pour le monde** ; la fromagerie **produit ce que le monde ne peut pas copier**, grâce à son terroir et son savoir-faire."},{"cle":{"type":"choix","ids":["c"]},"explication":"Compétitivité et **ancrage territorial** ne pointent pas toujours dans la même direction : c’est l’arbitrage au cœur du chapitre."}]$ex$::jsonb),
  ('f944fe8e-b8af-5617-b96f-89ae6c55ad0e'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le solde qui nuance tout","competence":"lire-tableau","situation":"Un conseiller économique imaginaire dresse le bilan des échanges de biens de la France. Il constate des points forts spectaculaires, mais un solde global qui n’est pas à l’avantage du pays.","documents":[{"id":"echanges","type":"tableau","titre":"Échanges de biens par secteur","source":"Chiffres inventés pour l’exercice (milliards d’euros).","colonnes":["Secteur","Exportations","Importations"],"lignes":[["Aéronautique",70,25],["Agroalimentaire",80,65],["Automobile",45,75],["Énergie",20,95]],"enteteLignes":true},{"id":"note","type":"texte","genre":"article","titre":"La note du conseiller","source":"Note imaginée pour l’exercice.","blocs":["La France exporte des avions, du champagne et du comté dans le monde entier. Pourtant elle importe, au total, plus de biens qu’elle n’en exporte."]}],"questions":[{"enonce":"Quel est le solde commercial de l’aéronautique (exportations moins importations), en milliards d’euros ?","aide":"Soustrais les importations aux exportations.","type":"nombre","unite":"milliards d’€"},{"enonce":"Touche la case qui montre le plus gros poste d’importations.","aide":"Cherche la plus grande valeur de la colonne des importations.","type":"zone","document":"echanges","multiple":false},{"enonce":"Quel est le solde de l’ensemble des quatre secteurs, en milliards d’euros ? (Exportations moins importations.)","aide":"Additionne les exportations, puis les importations, et compare.","type":"nombre","unite":"milliards d’€"},{"enonce":"Que nuance ce solde négatif dans le bilan de la France ?","aide":"Compare le solde de l’aéronautique et le solde de l’ensemble.","type":"choix","options":[{"id":"a","texte":"L’aéronautique est le seul secteur qui commerce avec l’étranger"},{"id":"b","texte":"La France n’exporte aucun produit de haute technologie"},{"id":"c","texte":"Les points forts exportateurs n’empêchent pas un déficit global"},{"id":"d","texte":"Les importations sont toujours plus faibles que les exportations"}],"multiple":false},{"enonce":"Range chaque produit : relève-t-il de « produire pour le monde » ou de « produire ce que le monde ne peut pas copier » ?","aide":"Les signes de qualité protègent un savoir-faire lié à un lieu.","type":"categories","categories":[{"id":"c0","texte":"Produire pour le monde"},{"id":"c1","texte":"Produire ce que le monde ne peut pas copier"}],"items":[{"id":"i0","texte":"Un cosmétique vendu par une grande firme dans de nombreux pays"},{"id":"i1","texte":"Un avion assemblé à Toulouse et vendu partout"},{"id":"i2","texte":"Un champagne produit sur son terroir"},{"id":"i3","texte":"Un comté d’AOP affiné dans le Jura"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":45,"tolerance":0},"affichage":"45 milliards d’€","explication":"70 − 25 = **+ 45 milliards d’euros** : l’aéronautique est un point fort exportateur."},{"cle":{"type":"zone","ids":["r3c2"]},"explication":"L’**énergie** pèse **95 milliards** d’importations : c’est le plus gros poste, bien devant l’automobile."},{"cle":{"type":"nombre","valeur":-45,"tolerance":0},"affichage":"−45 milliards d’€","explication":"Exportations : 70 + 80 + 45 + 20 = 215. Importations : 25 + 65 + 75 + 95 = 260. 215 − 260 = **− 45** : le solde est déficitaire, comme la balance commerciale des biens de la France."},{"cle":{"type":"choix","ids":["c"]},"explication":"La balance commerciale française est **déficitaire** : elle importe plus de biens qu’elle n’en exporte. C’est le chiffre qui nuance tout le reste."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1"}},"explication":"Avions et cosmétiques sont des produits de **firmes transnationales** qui visent le monde ; comté et champagne sont **liés à un terroir** : le monde ne peut pas les copier."}]$ex$::jsonb),
