   $ex$[{"cle":{"type":"zone","ids":["k0"]},"explication":"Les **agriculteurs** ne représentent que 7 % des actifs de la commune : une petite minorité."},{"cle":{"type":"nombre","valeur":93,"tolerance":0},"affichage":"93 %","explication":"100 − 7 = **93 %** : le rural d’aujourd’hui n’est plus défini par l’agriculture seule."},{"cle":{"type":"choix","ids":["d"]},"explication":"Autrefois, **rural = agricole**. Aujourd’hui, on y trouve des employés, des ouvriers, des retraités et des télétravailleurs."},{"cle":{"type":"trous","trous":[["continuum"]]},"affichage":"continuum","explication":"Le **continuum urbain-rural** décrit un dégradé entre la ville et la campagne, sans frontière nette."}]$ex$::jsonb),
