  ('0bce972f-9de5-5079-b573-8346a54e35e6'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une journée au village de Valmeyrac","competence":"analyser-texte","situation":"Noé passe les vacances dans un village de moyenne montagne. Il note tout ce qu’il voit : il découvre que la campagne ne sert pas qu’à cultiver.","documents":[{"id":"village","type":"texte","genre":"recit","titre":"Le carnet de Noé","source":"Texte écrit pour l’exercice (village imaginaire).","blocs":["Le matin, la ferme des Roux livre son lait à la laiterie voisine, et la scierie s’active. Dans les rues, beaucoup de volets sont fermés : ce sont des résidences secondaires, que leurs propriétaires parisiens n’ouvrent qu’en août.","L’après-midi, des randonneurs suivent le sentier qui monte au col. Au-dessus, une zone Natura 2000 protège les tourbières et les oiseaux rares."]}],"questions":[{"enonce":"Associe chaque observation de Noé à la fonction qu’elle illustre.","aide":"Production, habitat, loisirs, protection.","type":"association","gauche":[{"id":"g0","texte":"La ferme et la scierie"},{"id":"g1","texte":"Les résidences secondaires"},{"id":"g2","texte":"Le sentier de randonnée"},{"id":"g3","texte":"La zone Natura 2000"}],"droite":[{"id":"d0","texte":"Fonction productive"},{"id":"d1","texte":"Fonction résidentielle"},{"id":"d2","texte":"Fonction écologique"},{"id":"d3","texte":"Fonction récréative"}]},{"enonce":"Touche le mot qui désigne ceux qui profitent de la fonction récréative.","aide":"Qui marche sur le sentier ?","type":"zone","document":"village","multiple":false},{"enonce":"Que montre le carnet de Noé sur les espaces ruraux d’aujourd’hui ?","aide":"Compte les fonctions repérées dans un seul village.","type":"choix","options":[{"id":"a","texte":"Une seule fonction, l’agriculture, y domine toujours"},{"id":"b","texte":"Les fonctions y sont rangées dans des lieux séparés"},{"id":"c","texte":"La production y a disparu au profit des loisirs"},{"id":"d","texte":"Plusieurs fonctions se superposent sur le même territoire"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g0":"d0","g1":"d1","g3":"d2","g2":"d3"}},"explication":"La ferme et la scierie relèvent de la fonction **productive** ; les résidences secondaires de la fonction **résidentielle** ; le sentier de la fonction **récréative** ; la zone Natura 2000 de la fonction **écologique**."},{"cle":{"type":"zone","ids":["m43"]},"explication":"Les **randonneurs** sont des visiteurs de loisirs : c’est la fonction récréative, celle des citadins qui viennent se détendre."},{"cle":{"type":"choix","ids":["d"]},"explication":"Les espaces ruraux sont **multifonctionnels** : plusieurs fonctions se **superposent** sur les mêmes territoires."}]$ex$::jsonb),
  ('0bce972f-9de5-5079-b573-8346a54e35e6'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les Diallo quittent la ville, Lina cherche un week-end vert","competence":"lire-tableau","situation":"La famille Diallo vient de quitter un appartement de ville pour une maison dans un village. Leur cousine Lina, restée en ville, compare leurs frais et leur quotidien avec les siens, puis cherche où partir pour un week-end de tourisme vert.","documents":[{"id":"carte","type":"carte","titre":"Où va le tourisme vert ?","source":"Carte simplifiée d’après le cours.","fond":"france","lieux":[{"id":"z1","lieu":"chamonix","symbole":"lettre","lettre":"A"},{"id":"z2","lieu":"arcachon","symbole":"lettre","lettre":"B"},{"id":"z3","lieu":"deauville","symbole":"lettre","lettre":"C"},{"id":"z4","lieu":"gueret","symbole":"lettre","lettre":"D"},{"id":"z5","lieu":"chartres","symbole":"lettre","lettre":"E"}]},{"id":"budget","type":"tableau","titre":"Deux familles, deux modes de vie","source":"Chiffres imaginés pour l’exercice.","colonnes":["","Famille de Lina (ville)","Famille Diallo (village)"],"lignes":[["Loyer ou mensualité","950 €","620 €"],["Trajet vers le travail","20 min en tramway","45 min en voiture"],["Distance au médecin","300 m","12 km"]],"enteteLignes":true}],"questions":[{"enonce":"Touche les trois lieux situés en montagne ou sur le littoral, où se concentrent les flux touristiques.","aide":"Cherche la montagne, puis deux sites au bord de la mer.","type":"zone","document":"carte","multiple":true},{"enonce":"Combien d’euros les Diallo économisent-ils chaque mois sur le logement ?","aide":"Soustrais les deux montants du tableau.","type":"nombre","unite":"€"},{"enonce":"Touche la case qui montre la forte dépendance des Diallo à la voiture.","aide":"Cherche le trajet quotidien en voiture.","type":"zone","document":"budget","multiple":false},{"enonce":"Quelle contrepartie la fonction résidentielle impose-t-elle à une famille comme les Diallo ?","aide":"Regarde les lignes « trajet » et « médecin ».","type":"choix","options":[{"id":"a","texte":"Un logement beaucoup plus cher qu’en ville"},{"id":"b","texte":"Des services plus éloignés et des trajets en voiture"},{"id":"c","texte":"L’obligation de travailler dans l’agriculture"},{"id":"d","texte":"L’interdiction de posséder une résidence secondaire"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1","z2","z3"]},"explication":"**A** (Chamonix, en montagne), **B** (Arcachon) et **C** (Deauville) sont sur le littoral ou en montagne. Guéret et Chartres sont des campagnes bien moins visitées."},{"cle":{"type":"nombre","valeur":330,"tolerance":0},"affichage":"330 €","explication":"950 − 620 = **330 €** d’économie par mois : c’est l’avantage du logement moins cher."},{"cle":{"type":"zone","ids":["r1c2"]},"explication":"La case **45 min en voiture** montre la dépendance à l’automobile, contrepartie de la vie à la campagne."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le logement moins cher a pour contrepartie une **forte dépendance à la voiture** et des **services publics plus éloignés**."}]$ex$::jsonb),
  ('0bce972f-9de5-5079-b573-8346a54e35e6'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Rochebrune : le même sol pour quatre projets","competence":"analyser-document","situation":"Dans la commune de Rochebrune, un éleveur, un lotisseur, une entreprise d’énergie et un hôtelier lorgnent les mêmes terrains. Le maire cherche si ces fonctions peuvent cohabiter.","documents":[{"id":"conseil","type":"texte","genre":"article","titre":"Compte rendu du conseil municipal","source":"Texte écrit pour l’exercice (commune imaginaire).","blocs":["L’éleveur veut garder ses prairies pour son troupeau. Le lotisseur propose de construire quarante maisons sur les mêmes prairies.","L’entreprise d’énergie projette un champ d’éoliennes en crête, alors que l’hôtelier craint que les pales ne gâchent la vue qui attire ses clients. Les deux projets s’opposent devant le conseil."]},{"id":"sols","type":"graphique","forme":"secteurs","titre":"Les usages du sol de la commune","source":"Chiffres imaginés pour l’exercice, en % de la surface.","categories":["Prairies et cultures","Forêt et espaces protégés","Habitat existant","Terrains convoités"],"series":[{"nom":"Part de la surface","valeurs":[55,25,6,14]}]}],"questions":[{"enonce":"Touche les deux mots qui montrent que ces fonctions entrent en conflit.","aide":"Cherche ce que redoute l’hôtelier et ce que font les deux projets.","type":"zone","document":"conseil","multiple":true},{"enonce":"Quelle part de la surface de la commune est occupée par les prairies, les cultures et les terrains convoités ensemble ?","aide":"Additionne les parts concernées.","type":"nombre","unite":"%"},{"enonce":"Range chaque situation : les fonctions se complètent ou s’excluent ?","aide":"Demande-toi si chaque activité aide l’autre ou lui prend sa place.","type":"categories","categories":[{"id":"c0","texte":"Elles se complètent"},{"id":"c1","texte":"Elles s’excluent"}],"items":[{"id":"i0","texte":"Des éoliennes qui masquent la vue vantée par un hôtel"},{"id":"i1","texte":"Une ferme qui vend ses produits aux hôtes du gîte voisin"},{"id":"i2","texte":"Un parc naturel qui finance un sentier et protège les haies"},{"id":"i3","texte":"Quarante maisons sur les prairies de l’éleveur"}]},{"enonce":"Quel mot décrit le mieux la situation de Rochebrune ?","aide":"Les fonctions s’y excluent.","type":"choix","options":[{"id":"a","texte":"Désertification"},{"id":"b","texte":"Périurbanisation réussie"},{"id":"c","texte":"Multifonctionnalité harmonieuse"},{"id":"d","texte":"Fragmentation"}],"multiple":false}]}$ex$::jsonb,
