alaires","mingong","impôts","remises"]},{"enonce":"Pourquoi dit-on que cette migration est « juridiquement organisée » ?","aide":"Pense à ce que décide le permis de résidence.","type":"choix","options":[{"id":"a","texte":"Les migrants reçoivent un logement gratuit en arrivant"},{"id":"b","texte":"L’État impose un salaire unique dans toutes les villes"},{"id":"c","texte":"Une loi interdit à tout paysan de quitter son village"},{"id":"d","texte":"Le hukou rattache chacun à son lieu d’origine"}],"multiple":false}]}$ex$::jsonb,
