   $ex${"titre":"Un hiver de pollution à Xinhe","competence":"analyser-document","situation":"Dans la ville imaginaire de Xinhe, dans le Nord, un hiver de pollution a tout changé. Mei, élève de 1re, relie ce récit à la politique nationale chinoise et aux chiffres des émissions.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"L’hiver où l’air est devenu gris","source":"Récit écrit pour l’exercice (ville imaginaire).","blocs":["À Xinhe, l’air est devenu gris dès novembre. Les chauffages et les usines à charbon crachaient jour et nuit. Les enfants toussaient à l’école et les hôpitaux s’emplissaient.","Les habitants se sont mobilisés : pétitions, manifestations pacifiques. La municipalité a fermé des usines et durci les normes de contrôle des émissions."]},{"id":"emissions","type":"graphique","forme":"barres-h","titre":"Part des émissions mondiales de CO2, vers 2022","source":"Ordres de grandeur arrondis, en %.","categories":["Chine","États-Unis","Inde","Union européenne"],"series":[{"nom":"Part des émissions","valeurs":[30,13,8,7],"teinte":"gris"}],"axeY":{"unite":"en %","min":0,"max":35,"pas":5},"valeurs":true}],"questions":[{"enonce":"Remets dans l’ordre la chaîne d’événements racontée à Xinhe.","aide":"Cause, conséquence sanitaire, réaction locale, réponse politique.","type":"ordre","items":[{"id":"a","texte":"Les pics de pollution deviennent fréquents"},{"id":"b","texte":"Les normes sont durcies et des usines fermées"},{"id":"c","texte":"Des enfants tombent malades"},{"id":"d","texte":"Les habitants se mobilisent"}]},{"enonce":"Touche le mot qui montre la réaction des habitants.","aide":"Quel verbe dit qu’ils se sont mis en mouvement ?","type":"zone","document":"recit","multiple":false},{"enonce":"De combien de points la part de la Chine dépasse-t-elle celle des États-Unis ?","aide":"Soustrais les deux valeurs du graphique.","type":"nombre","unite":"points"},{"enonce":"Associe chaque problème à la réponse de la Chine.","aide":"Une réponse par problème : eau, air, approvisionnement, climat.","type":"association","gauche":[{"id":"g0","texte":"Le manque d’eau au Nord"},{"id":"g1","texte":"Les pics de pollution de l’air"},{"id":"g2","texte":"La dépendance extérieure en ressources"},{"id":"g3","texte":"Les émissions de CO2"}],"droite":[{"id":"d0","texte":"Des normes plus strictes et des usines fermées"},{"id":"d1","texte":"L’objectif de neutralité carbone en 2060"},{"id":"d2","texte":"Le transfert Sud-Nord"},{"id":"d3","texte":"Les nouvelles routes de la soie"}]},{"enonce":"Que signifie « les corrections chinoises se font à la même échelle que les dégâts » ?","aide":"Pense au transfert Sud-Nord, aux renouvelables, aux fermetures d’usines.","type":"choix","options":[{"id":"a","texte":"Les réponses sont aussi gigantesques que les problèmes"},{"id":"b","texte":"Les corrections coûtent beaucoup moins cher que les dégâts"},{"id":"c","texte":"Les dégâts ont disparu dès les premières mesures prises"},{"id":"d","texte":"La Chine corrige ses dégâts seulement à l’échelle locale"}],"multiple":false}]}$ex$::jsonb,
