  ('521d5941-4d01-5a3a-94fa-79d2d33b6f26'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le village de Mingyu","competence":"analyser-texte","situation":"Mingyu, 14 ans, vit dans un village du centre de la Chine. Ses parents travaillent dans une usine de la côte : sa vie raconte celle de centaines de millions de ruraux.","documents":[{"id":"village","type":"texte","genre":"recit","titre":"Le village de Mingyu","source":"Récit écrit pour l’exercice (village imaginaire).","blocs":["Mingyu vit avec sa grand-mère. Ses parents sont partis travailler à la ville : ils sont ce qu’on appelle des mingong. Dans les ruelles, on croise surtout des enfants et des personnes âgées.","Chaque mois, ses parents envoient de l’argent au village : il fait vivre toute la maison. Les champs appartiennent au collectif du village : la famille ne possède que le droit de les utiliser."]}],"questions":[{"enonce":"Touche le mot qui désigne ce que les parents envoient chaque mois (les remises).","aide":"Qu’envoie-t-on à sa famille pour la faire vivre ?","type":"zone","document":"village","multiple":false},{"enonce":"Qui vit surtout dans le village de Mingyu ?","aide":"Les actifs sont partis à la ville.","type":"choix","options":[{"id":"a","texte":"Des enfants et des personnes âgées"},{"id":"b","texte":"Des ouvriers venus de la ville"},{"id":"c","texte":"Des touristes étrangers"},{"id":"d","texte":"Des cadres et des ingénieurs"}],"multiple":false},{"enonce":"Que possède la famille de Mingyu sur ses champs ?","aide":"Relis la dernière phrase du récit.","type":"choix","options":[{"id":"a","texte":"La moitié de la propriété, l’autre moitié à l’État"},{"id":"b","texte":"Rien, ils n’ont jamais le droit d’y cultiver"},{"id":"c","texte":"Seulement le droit de les utiliser"},{"id":"d","texte":"La pleine propriété, avec le droit de les vendre"}],"multiple":false}]}$ex$::jsonb,
